const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(input[0], 10);
const s = input[1];

let maxLen = 1;

function expand(l, r) {
    while (l >= 0 && r < n && s[l] === s[r]) {
        l--;
        r++;
    }
    return r - l - 1;
}

for (let i = 0; i < n; i++) {
    maxLen = Math.max(maxLen, expand(i, i));
    maxLen = Math.max(maxLen, expand(i, i + 1));
}

console.log(maxLen);
